function e(e){let n=e=>String(e).padStart(2,`0`);return`${t(e)} ${n(e.getHours())}:${n(e.getMinutes())}:${n(e.getSeconds())}`}function t(e){let t=e=>String(e).padStart(2,`0`);return`${e.getFullYear()}-${t(e.getMonth()+1)}-${t(e.getDate())}`}function n(){return e(new Date)}function r(e,n){let r=new Date(`${e}T00:00:00`);return r.setDate(r.getDate()+n),t(r)}function i(e,t){let n=new Date(e.getTime());if(t>=60){let e=Math.floor(t/60);n.setMinutes(0,0,0),n.setHours(Math.floor(n.getHours()/e)*e)}else n.setSeconds(0,0),n.setMinutes(Math.floor(n.getMinutes()/t)*t);return n}export{r as i,e as n,n as r,i as t};